  const visibleFields = fields.filter(f => f.value !== undefined && f.value !== null && f.value !== '');

  return (
    <div>
      <h3 style={{ fontSize: 15, fontWeight: 800, color: 'var(--ink)', margin: '0 0 12px' }}>📄 रिपोर्ट डेटा</h3>
      <div className="tbl-wrap" style={{ border: '1px solid var(--line)', borderRadius: 14 }}>
        <table className="report-data-table">
          <tbody>
            {visibleFields.map((f, idx) => (
              <tr key={idx}>
                <th style={{ width: '42%' }}>{f.label}</th>
                <td style={{ color: 'var(--ink)', fontWeight: 600 }}>{f.value}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
